import {unitEconomics} from './economics.js';
import {styles,referenceNotes} from './plan.js';
export const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export async function buyerSheet(project,result,image){const esc=escapeHTML,s=project.templates[project.type];const data=await new Promise(ok=>{const fr=new FileReader();fr.onload=()=>ok(fr.result);fr.readAsDataURL(image);});const rows=project.catalog.filter(p=>result.counts[p.id]).map(p=>`<tr><td>${esc(p.sku)}</td><td>${esc(p.name)}</td><td>${p.w} × ${p.d} × ${p.h}</td><td>${result.counts[p.id]}</td><td>${unitEconomics(p).msrp===null?'—':unitEconomics(p).msrp.toFixed(2)}</td></tr>`).join('');return new Blob([`<!doctype html><html lang="en"><head><meta charset="utf-8"><title>${esc(project.name)} | Buyer concept</title><style>body{font:14px Arial;color:#17344d;max-width:900px;margin:35px auto;padding:20px}header{border-bottom:3px solid #0071ce;padding-bottom:15px}small{color:#758798}h1{font-size:28px}img{display:block;width:100%;max-height:600px;object-fit:contain}table{width:100%;border-collapse:collapse;margin:20px 0}td,th{padding:10px;text-align:left;border-bottom:1px solid #ddd}p{line-height:1.6}button{background:#0071ce;color:white;border:0;padding:12px 20px;border-radius:5px}@media print{button{display:none}body{margin:0}img{max-height:440px}}</style></head><body><header><b>DISPLAY STUDIO / 2.0</b> · BUYER CONCEPT</header><h1>${esc(project.name)}</h1><p>${esc(styles[project.type])} · ${s.width}″ W × ${s.depth}″ D × ${s.height}″ H<br>${result.total} units placed · ${result.unused} unfilled assigned positions<br>${esc(referenceNotes(s).join(' '))}</p><img src="${data}" alt="Configured display"><table><thead><tr><th>SKU</th><th>Product</th><th>W × D × H (in)</th><th>Units</th><th>MSRP (USD)*</th></tr></thead><tbody>${rows}</tbody></table><small>*User-entered MSRP in USD, an illustrative assumed selling price; not retailer approved. Confidential supplier costs and profitability are excluded. Dimensions reference the supplied 2017 Canada guide, not current Walmart US approval. Images and models are user-supplied; unknown surfaces are neutral approximations. Structural, weight, shipping, stability and shopper-access validation require engineering and merchant review. The sign is a placeholder only. No logos, prices or promotional claims are generated.</small><p><button onclick="window.print()">Print / Save as PDF</button></p></body></html>`],{type:'text/html'});}
